var BREAK=['SELECT','FROM','WHERE','GROUP BY','ORDER BY','HAVING','LIMIT','OFFSET','LEFT JOIN','RIGHT JOIN','INNER JOIN','FULL JOIN','CROSS JOIN','JOIN','ON','UNION ALL','UNION','INSERT INTO','VALUES','UPDATE','SET','DELETE FROM','AND','OR'];
var UPPER=['SELECT','FROM','WHERE','GROUP BY','ORDER BY','HAVING','LIMIT','OFFSET','LEFT JOIN','RIGHT JOIN','INNER JOIN','FULL JOIN','CROSS JOIN','JOIN','ON','UNION ALL','UNION','INSERT INTO','VALUES','UPDATE','SET','DELETE FROM','AND','OR','AS','IN','NOT','NULL','IS','LIKE','BETWEEN','DISTINCT','CASE','WHEN','THEN','ELSE','END'];
function format(sql){
  var s=sql.replace(/\s+/g,' ').trim();
  BREAK.forEach(function(k){ var re=new RegExp('\\s*\\b'+k.replace(/ /g,'\\s+')+'\\b','gi'); s=s.replace(re,'\n'+k.toUpperCase()); });
  UPPER.forEach(function(k){ var re=new RegExp('\\b'+k.replace(/ /g,'\\s+')+'\\b','g'); s=s.replace(re,k.toUpperCase()); });
  s=s.replace(/^\n+/,'').replace(/\n{2,}/g,'\n');
  return s;
}
var EXPORTS={format:format};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SqlFormatForgePure = EXPORTS; }
